<script setup lang="ts">defineProps<{items:{id:string;subject_type:string;state:string;priority:number;risk_score:number;action:string;trust_score:number;sla_due_at:string}[];selected?:string}>();const emit=defineEmits<{select:[id:string]}>();const fa=(value:number)=>value.toLocaleString('fa-IR');</script>
<template><section class="risk-panel risk-queue"><header><div><h2>صف بررسی ریسک</h2><p>مرتب‌شده بر پایه شدت، SLA و اثر مالی</p></div><span class="admin-chip">{{fa(items.length)}} پرونده</span></header><button v-for="item in items" :key="item.id" type="button" :class="{selected:item.id===selected}" @click="emit('select',item.id)"><span class="risk-priority" :data-level="item.risk_score>=800?'critical':item.risk_score>=600?'warning':'review'">{{fa(item.risk_score)}}</span><div><b>{{item.subject_type==='payment'?'پرداخت مشکوک':'حساب کاربری مشکوک'}}</b><small>اعتماد {{fa(item.trust_score)}} · اولویت {{fa(item.priority)}}</small></div><em>{{item.state==='claimed'?'در اختیار کارشناس':'باز'}}</em></button></section></template>
